    pub fn remove(&mut self, alias: &str) -> Result<Option<String>, StorageError> {
        let output = self.alias_mapping.0.remove(alias);   // HashMap::remove -> None when absent
        if output.is_some() {
            self.alias_mapping.save(&self.data_path)?;
        }
        Ok(output)   // <-- unknown alias: Ok(None) propagated as success -> handler 200 {"result":true}
    }

